function ProductCalendar(){
    var me = this;
    var sdate = null;
    var productcode = null;
    this.loadEvent = function() {
        sdate = $('.sdate').html();
        productcode = $('.productcode').html();
        $('#calendar').fullCalendar({
            header: {
                left: 'prev,next',
                center: 'title',
                right: ''
            },
            defaultDate: moment(sdate),
            selectable: true,
            selectHelper: true,
            dayClick: function(date, jsEvent, view, resourceObj) {
                me.gotoDate(date.format());
            },
            editable: true,
            eventLimit: true, // allow "more" link when too many events
            eventSources: [
                // your event source
                {
                    events: function (start, end, timezone, callback) {
                        $.ajax({
                            url: '/loyalty/'+productcode+'/product-calendar.json?start=' + start.unix(),
                            type: 'GET',
                            cache: false,
                            contentType: "application/json",
                            dataType: 'json',
                            success: function (res) {
                                if (res.success) {
                                    callback(res.data);
                                } else {
                                    callback([]);
                                }
                            },
                            error: function (data, status, er) {
                            }
                        });
                    },
                    durationEditable: false,
                    startEditable: false,
                    color: '#e3e3e3',   // an option!
                    //textColor: 'white' // an option!
                },
                // any other sources...
            ],
            eventRender: function (event, element) {
                var ss = element.find('span.fc-title').text();
                if (ss.indexOf("Available: 0") >=0 ) {
                    ss = ss.replace("calendar-special","calendar-special zero");
                }
                element.find('span.fc-title').html(ss);
            },
            eventClick: function(calEvent, jsEvent, view) {
                me.showEventDetail(calEvent.start.format());
            }
        });
    }

    this.showEventDetail = function(d) {
        if (d != sdate) {
            window.location = '/' + productcode + '.html?sdate='+d;
        }
    };

    this.gotoDate = function(d) {
        if (d != sdate) {
            window.location = '/' + productcode + '.html?sdate='+d;
        }
    };
}
var PRODUCT_CALENDAR = new ProductCalendar();
function chooseAppointment(ele) {
    var appointmentid = $(ele).data('appointmentid');
    $('.js-choose-appointment').removeClass('btn-primary');
    $(ele).removeClass('btn-primary').addClass('btn-primary');
    $('#btnBookNow').removeClass('d-none');
}
function bookAppointment(ele) {
    var $appointmentChoosed = $($('.js-choose-appointment.btn-primary')[0])
    var appointmentid = $appointmentChoosed.data('appointmentid');
    var qty = $('.custom-select.quantity-'+appointmentid).val();
    qty = qty > 0 ? qty : 1;
    if (qty > 0) {
        var productcode = $('.productcode').html();
        window.location = '/' + productcode + '/book-now.html?aptid='+appointmentid+'&qty='+qty;
    } else {
        $('.custom-select.quantity-'+appointmentid).focus();
    }
}
$(document).ready(function() {
    $("#productSlider").lightSlider({
        gallery: true,
        item: 1,
        loop: true,
        slideMargin: 0,
        thumbItem: 9
    });
    $('.plus-btn').click(function(){
        var rateid = $(this).attr('id').split('_')[1];
        var max = parseInt($('.quantity-'+rateid).attr('max'));
        var qty = parseInt($('.quantity-'+rateid).val());
        if (qty < max) {
            qty++;
            $('.quantity-'+rateid).val(qty);
        }
    });
    $('.minus-btn').click(function(){
        var rateid = $(this).attr('id').split('_')[1];
        var min = parseInt($('.quantity-'+rateid).attr('min'));
        var qty = parseInt($('.quantity-'+rateid).val());
        if (qty > min) {
            qty--;
            $('.quantity-'+rateid).val(qty);
        }
    });
    PRODUCT_CALENDAR.loadEvent();
});



